def binary_search(items, target):
    """Return the index of target in a sorted list, or -1."""
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

class LruCache:
    """Fixed-capacity cache that evicts the least recently used key."""
    def __init__(self, capacity):
        self.capacity = capacity
        self._data = {}
        self._order = []

    def get(self, key):
        if key not in self._data:
            return None
        self._order.remove(key)
        self._order.append(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._order.remove(key)
        elif len(self._data) >= self.capacity:
            oldest = self._order.pop(0)
            del self._data[oldest]
        self._data[key] = value
        self._order.append(key)

def largest_remainder(shares, total):
    """Allocate `total` integer slots across float shares without drift."""
    exact = {k: v * total for k, v in shares.items()}
    out = {k: int(v) for k, v in exact.items()}
    short = total - sum(out.values())
    order = sorted(exact, key=lambda k: (-(exact[k] - out[k]), k))
    for k in order[:short]:
        out[k] += 1
    return out

def retry(times, exceptions=(OSError,)):
    """Decorator that retries a call a fixed number of times."""
    def wrap(fn):
        def inner(*args, **kwargs):
            last = None
            for attempt in range(times):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    last = exc
            raise last
        return inner
    return wrap

def chunk(seq, size):
    """Split a sequence into consecutive chunks of at most `size`."""
    if size <= 0:
        raise ValueError("size must be positive")
    return [seq[i:i + size] for i in range(0, len(seq), size)]


def flatten(nested):
    """One level of flattening, preserving order."""
    out = []
    for part in nested:
        out.extend(part)
    return out

import hashlib


def content_hash(payload):
    """Stable hash of a mapping, independent of key insertion order."""
    items = sorted(payload.items())
    joined = "|".join(f"{k}={v}" for k, v in items)
    return hashlib.sha256(joined.encode("utf-8")).hexdigest()

def parse_csv_line(line, sep=","):
    """Split one CSV line, honouring double quotes."""
    fields, current, in_quotes = [], [], False
    for ch in line:
        if ch == '"':
            in_quotes = not in_quotes
        elif ch == sep and not in_quotes:
            fields.append("".join(current))
            current = []
        else:
            current.append(ch)
    fields.append("".join(current))
    return fields
